-- 4) MONITORING VIEWS (one per root cause) ---------------------------------
CREATE OR REPLACE VIEW monitoring.v_sec_sql_scp_001_rc01 AS
SELECT r.server,
    (j.value ->> 'event_time') AS event_time,
    (j.value ->> 'principal') AS principal,
    (j.value ->> 'command') AS command,
    r.entry_date
FROM monitoring.general_metric_metadata_results r
  CROSS JOIN LATERAL jsonb_array_elements(r.metric_metadata) j(value)
 WHERE r.metric_name = 'SEC-SQL-SCP-001-RC01';

CREATE OR REPLACE VIEW monitoring.v_sec_sql_scp_002_rc01 AS
SELECT r.server,
    (j.value ->> 'schema') AS schema,
    (j.value ->> 'table_name') AS table_name,
    (j.value ->> 'trigger_name') AS trigger_name,
    (j.value ->> 'function_name') AS function_name,
    (j.value ->> 'owner') AS owner,
    r.entry_date
